    [SuppressMessage("Microsoft.StyleCop.CSharp.DocumentationRules", "SA1600:ElementsMustBeDocumented")]
    public class StatementSMAController : BaseController
    {
        private readonly IStatementService _statementService;
        private const string MainAction = "Index";

        public StatementSMAController() :
            this(null)
        {
        }

        public StatementSMAController(IStatementService statementService)
        {
            _statementService = statementService ?? new StatementService();
        }

        [HttpGet]
        [StatementSMAAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        public ActionResult Index(int CustID, int RoleID, string username)
        {
            ViewBag.CustID = CustID;
            ViewBag.RoleID = RoleID;
            ViewBag.Username = string.IsNullOrEmpty(username) ? UserSession.Current.UserName : username;
            ViewBag.ReportMinDate = ReportDateTimeRange[0];
            return View("~/Areas/Finance/Views/Statement/StatementSMA/Index.cshtml");
        }

        [HttpPost]
        [StatementSMAAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        [HandleActionErrorAttribute]
        public JsonResult GetStatementSMA(string FromDate, string ToDate, int CustID, int RoleID)
        {
            StatementSMACriteria criteria = new StatementSMACriteria
            {
                FromDate = Converter.ToDateTime(FromDate),
                ToDate = Converter.ToDateTime(ToDate),
                CustID = CustID,
                BalanceUpDay = ReportService.BalanceUp.BalanceUpDay,
                PageIndex = 0,
                PageSize = 0,
                RoleID = RoleID
            };
            var statementList = _statementService.GetStatementSMA(criteria);
            Session[CacheServiceKey.SessionKeyStatement] = statementList;

            return Json(statementList, JsonRequestBehavior.AllowGet);
        }

        [StatementSMAAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        public ActionResult ExportExcelStatementSMA(string FromDate, string ToDate, int CustID, int RoleID)
        {
            StatementSMACriteria criteria = new StatementSMACriteria
